  for (const f of ['settings-file.mjs', 'settings-file-names.mjs']) cpSync(join(REPO_ROOT, 'engine', f), join(root, 'engine', f));
  for (const [id, { proseText, manifestSource, ...manifest }] of Object.entries(packs)) {
