  const v = fm?.metadata && typeof fm.metadata === 'object' && !Array.isArray(fm.metadata) ? fm.metadata[key] : undefined;
  return Array.isArray(v) ? v : typeof v === 'string' && v.trim() ? [v] : [];
};

